import 'client.dart';
class FlutterNotificationSDK { final FenlengFlutterClient client; FlutterNotificationSDK({required this.client}); Future<Map<String,dynamic>> registerToken(String token,String deviceId,String idempotencyKey)=>client.request('/api/platform/v1/users/me/notification-subscriptions',method:'POST',body:{'channel':'PUSH','deviceId':deviceId,'endpoint':token,'keys':<String,String>{}},idempotencyKey:idempotencyKey); Future<Map<String,dynamic>> preference(String purpose,bool enabled,String policyVersion)=>client.request('/api/platform/v1/users/me/consents',method:'PUT',body:{'purpose':purpose,'granted':enabled,'policyVersion':policyVersion,'notificationEnabled':enabled}); Future<Map<String,dynamic>> inbox()=>client.request('/api/platform/v1/users/me/notifications'); }
class FlutterFeedbackSDK { final FenlengFlutterClient client; final String projectId,version; final String? traceId; FlutterFeedbackSDK({required this.client,required this.projectId,required this.version,this.traceId}); Future<Map<String,dynamic>> submit(String message,String idempotencyKey,{String? screenshot,String? logs,bool attachmentConsent=false}){if((screenshot!=null||logs!=null)&&!attachmentConsent)throw const FenlengSdkException('ATTACHMENT_CONSENT_REQUIRED','Attachment consent is required');return client.request('/api/platform/v1/feedback',method:'POST',body:{'projectId':projectId,'version':version,'traceId':traceId,'message':message,'attachmentConsent':attachmentConsent,'attachments':[if(screenshot!=null){'type':'SCREENSHOT','content':screenshot},if(logs!=null){'type':'LOGS','content':logs}]},idempotencyKey:idempotencyKey);} }
